type NoteOutput = { title: string; updatedAt: Date };
type NoteViewModel = { title: string; updatedAt: string };

// O apresentador decide o formato; a visão só exibe
function presentNote(output: NoteOutput): NoteViewModel {
	return {
		title: output.title,
		updatedAt: output.updatedAt.toISOString().slice(0, 10),
	};
}

